    #[test]
    fn test_vlq_parsing() {
        // 0x00 = 0
        let mut pos = 0;
        assert_eq!(read_vlq(&[0x00], &mut pos).unwrap(), 0);

        // 0x7F = 127
        pos = 0;
        assert_eq!(read_vlq(&[0x7F], &mut pos).unwrap(), 127);

        // 0x81 0x00 = 128
        pos = 0;
        assert_eq!(read_vlq(&[0x81, 0x00], &mut pos).unwrap(), 128);

        // 0x83 0x60 = 480
        pos = 0;
        assert_eq!(read_vlq(&[0x83, 0x60], &mut pos).unwrap(), 480);
    }

